 const dynamic=f.dynamic?.(state),label=dynamic?.[0]||f.label,unit=dynamic?.[1]??f.unit,value=state[f.key],id=`field-${f.key}`,type=f.type;let options=typeof f.options==='function'?f.options(state):f.options;
