  const options=[[0,optional?'Leave blank · show acceptable range':'Choose a rating'],...ratings.map(v=>[v,`${v} A${v<current&&Math.abs(v-current)>Math.max(1,Math.abs(v),Math.abs(current))*1e-12?' · partial capacity':''}`])];
